      }
      if (bitsRead >>> 3 < tailBase) {
        window =
            view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
      } else {
        window = tailWord >>> (bitsRead - tailBase * 8);
      }
      v = window & 0x3;
      bitsRead += 2;
      if (v > 2) {
        return false; // the count guards the loop — reject, never clamp
      }
      value.second.payload.entriesCount = v;
      if (bitsRead + value.second.payload.entriesCount * 36 > numBits) {
        return false;
      }
      for (var i0 = 0; i0 < value.second.payload.entriesCount; i0++) {
        final e0 = value.second.payload.entries[i0];
        if (bitsRead >>> 3 < tailBase) {
          window =
              view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
        } else {
          window = tailWord >>> (bitsRead - tailBase * 8);
        }
        v = window & 0xffffffff;
        bitsRead += 32;
        e0.retries = (v << 32) >> 32;
        v = (window >>> 32) & 0xf;
        bitsRead += 4;
        e0.preferred = v;
      }
      if (bitsRead + 3 > numBits) {
        return false;
      }
      if (bitsRead >>> 3 < tailBase) {
        window =
            view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
      } else {
        window = tailWord >>> (bitsRead - tailBase * 8);
      }
      v = window & 0x7;
      bitsRead += 3;
      value.second.payload.marker = v;
      if (bitsRead + 2 > numBits) {
        return false;
      }
      v = (window >>> 3) & 0x3;
      bitsRead += 2;
      if (v > 2) {
        return false; // the length guards the slice — reject, never clamp
      }
      value.second.dataLength = v;
      {
        final pad = bitsRead & 7;
        if (pad != 0) {
          if (bitsRead + (8 - pad) > numBits) {
            return false;
          }
          if (view.getUint8(bitsRead >>> 3) >>> pad != 0) {
            return false; // nonzero padding is refused (SPEC §4.3)
          }
          bitsRead += 8 - pad;
        }
      }
      if (bitsRead + value.second.dataLength * 8 > numBits) {
        return false;
      }
      {
        final base = bitsRead >>> 3;
        for (var i0 = 0; i0 < value.second.dataLength; i0++) {
          value.second.data[i0] = view.getUint8(base + i0);
        }
      }
      bitsRead += value.second.dataLength * 8;
  }
  return true;
}

// measureDefaultBulkChoice is the exact wire bits writeDefaultBulkChoice would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureDefaultBulkChoice(DefaultBulkChoice value) {
  var bits = 0;
  bits += 2;
  switch (value.type) {
    case 1:
      bits += 2;
      bits += value.first.payload.entriesCount * 36;
      bits += 5;
      bits += (8 - (bits & 7)) & 7;
      bits += value.first.dataLength * 8;
    case 2:
      bits += 2;
      bits += value.second.payload.entriesCount * 36;
      bits += 5;
      bits += (8 - (bits & 7)) & 7;
      bits += value.second.dataLength * 8;
  }
  return bits;
}
